"""Tests for verify_cold_init_trials.py on evidence generated by a model of the fault firmware and of the runner's frame sequence; no board is needed."""

import ast
import contextlib
import io
import json
import os
import struct
import tempfile
import unittest
import zlib

import epoch_wire as w
import verify_cold_init_trials as v

MAGIC, CAUSE, BOR = 0x45504301, 0x14004400, 1 << 27


def crc(ws):
    return zlib.crc32(struct.pack("<7I", *ws[:7]))


def newest(slots, era):
    ok = [era != 0 and slots[8 * i] == MAGIC and slots[8 * i + 1] == era and crc(slots[8 * i:]) == slots[8 * i + 7] for i in (0, 1)]
    if era != 0 and any(not ok[i] and slots[8 * i] != 0 for i in (0, 1)):
        return "inconsistent"
    if all(ok):
        d = (slots[6] - slots[14]) % 2**32
        return 0 if d == 1 else 1 if d == 2**32 - 1 else "inconsistent"
    return 0 if ok[0] else 1 if ok[1] else None


class Board:
    """The v5 fault firmware's journal, boots and replies, driven in the order cold_init_trials.py drives it."""

    def __init__(self):
        self.ids, self.era, self.slots, self.run, self.marker = iter(range(0x1000, 0x7FFFFFFF, 7)), 0x0E0, [0] * 16, 0, None
        self.boot(cold=False)

    def boot(self, cold):
        self.boot_id, self.ann_era, self.ann_slots = next(self.ids), self.era, list(self.slots)
        n = newest(self.slots, self.era) if not cold and self.era else "inconsistent"
        self.valid = n != "inconsistent"
        self.counter = self.slots[8 * n + 5] if isinstance(n, int) else 0
        if not self.valid:
            self.cold_init()

    def cold_init(self, stop=None):
        """The stores 9 to 12 in firmware order; returns True when the armed store was reached."""
        for index, store in ((9, lambda: setattr(self, "era", 0)), (10, lambda: self.slots.__setitem__(0, 0)), (11, lambda: self.slots.__setitem__(8, 0)), (12, lambda: setattr(self, "era", next(self.ids)))):
            store()
            if index == stop:
                return True
        return False

    def publish(self, s, txid):
        n = newest(self.slots, self.era)
        r = [MAGIC, self.era, s & 0xFFFFFFFF, s >> 32, txid, self.counter, 0 if n is None else self.slots[8 * n + 6] + 1]
        o = 8 if n == 0 else 0
        self.slots[o:o + 8] = r + [crc(r)]

    def announce(self, nonce=None):
        return dict(type="ANNOUNCE", boot_id=self.boot_id, challenge=self.boot_id * 3, nonce=nonce or 0, reset_cause=CAUSE, version_min=1, version_max=1, capabilities=0, era=self.ann_era,
                    nonce_echo=nonce is not None, retention_valid=self.valid, **{f"slot{i}": x for i, x in enumerate(self.ann_slots)})


def replies(events, note, nth=0):
    """The messages received after the nth sent frame of type note, as the runner keeps them in the record."""
    out, k, on = [], -1, False
    for e in events:
        if e["dir"] == "tx":
            k += e["note"] == note
            on = e["note"] == note and k == nth
        elif e["dir"] == "rx" and on:
            out.append(e["msg"])
    return out


class Runner:
    def __init__(self, board):
        self.b, self.events = board, []

    def ev(self, **e):
        self.events.append(dict(e, t=len(self.events) / 1000))

    def tx(self, **m):
        self.ev(dir="tx", note=m["type"], hex=w.encode(m).hex())

    def rx(self, **m):
        frame = w.encode(m)
        self.ev(dir="rxraw", hex=frame.hex())
        for status, msg in w.Parser().feed(frame):
            self.ev(dir="rx", status=status, msg=msg)

    def replies(self, note, nth=0):
        return replies(self.events, note, nth)

    def bind(self):
        b, nonce = self.b, next(self.b.ids)
        self.tx(type="PROBE", nonce=nonce)
        a = b.announce(nonce)
        self.rx(**a)
        s = next(b.ids)
        self.tx(type="HELLO", challenge=a["challenge"], nonce=nonce, version=1)
        self.rx(type="HELLO_ACK", challenge=a["challenge"], nonce=nonce, session=s)
        self.tx(type="START", session=s)
        b.publish(s, 0)
        self.rx(type="START_ACK", session=s)
        return b.boot_id, s

    def increment(self, s, txid):
        self.tx(type="INCREMENT", session=s, txid=txid)
        self.b.counter += 1
        self.b.publish(s, txid)
        self.rx(type="EP1_REPLY", session=s, txid=txid, ep1_status=0, counter=self.b.counter)
        return self.b.counter

    def arm(self, code, mode):
        self.b.run += 1
        self.tx(type="TEST_ARM", run=self.b.run, checkpoint=code, txid=mode)
        self.rx(type="TEST_ARM_ACK", run=self.b.run, checkpoint=code, txid=mode)
        return self.b.run

    def diag(self, run):
        self.tx(type="TEST_DIAG", run=run)
        r, cp, tx = self.b.marker
        self.rx(type="TEST_DIAG_REPLY", marker_valid=1, run=r, checkpoint=cp, txid=tx, reset_cause=CAUSE)

    def f3(self, s, txid):
        run = self.arm(4, txid)
        self.tx(type="INCREMENT", session=s, txid=txid)
        self.b.counter += 1
        self.b.publish(s, txid)
        self.b.marker = (run, 4, txid)
        self.b.boot(cold=False)
        self.rx(**self.b.announce())
        self.bind()
        self.diag(run)
        return run


def sync(b):
    r = Runner(b)
    _, s = r.bind()
    r.f3(s, 1)
    return {"kind": "sync", "events": r.events}


def cold(b, cut, mode, layout=0):
    r = Runner(b)
    boot, s = r.bind()
    txids = [1, 2] if newest(b.slots, b.era) == layout else [1, 2, 3]
    counters = [r.increment(s, t) for t in txids]
    run = r.arm(cut, mode)
    r.rx(type="TEST_DIAG_REPLY", marker_valid=0, run=run, checkpoint=cut, txid=mode, reset_cause=CAUSE)  # the boot after the preparatory reset
    assert b.cold_init(stop=cut)
    b.marker = (run, cut, mode)
    b.boot(cold=mode == 0)
    r.rx(**b.announce())
    r.bind()
    r.diag(run)
    return {"kind": "cold", "run": run, "code": cut, "mode": mode, "layout": layout, "session": s, "txids": txids, "counters": counters, "boot_before": boot,
            "after": r.replies("TEST_ARM"), "diag": r.replies("TEST_DIAG")[0], "classes": ["UNKNOWN"] * len(txids), "verdict": "COUNTED_PASS", "why": "", "events": r.events}


def forge(b, mode):
    r = Runner(b)
    boot, s = r.bind()
    counters = [r.increment(s, 1)]
    run = r.arm(13, mode)
    n = newest(b.slots, b.era)
    rec = b.slots[8 * n:8 * n + 8]
    rec[6] += 2 if mode == 0 else 0
    rec[7] = crc(rec)
    b.slots[8 * (1 - n):8 * (1 - n) + 8] = rec
    b.marker = (run, 13, mode)
    b.boot(cold=False)
    r.rx(**b.announce())
    _, s2 = r.bind()
    r.diag(run)
    c = r.increment(s2, 1)
    rrun = r.f3(s2, 2)
    return {"kind": "forge", "run": run, "code": 13, "mode": mode, "session": s, "txids": [1], "counters": counters, "boot_before": boot, "classes": ["UNKNOWN"],
            "after": r.replies("TEST_ARM"), "diag": r.replies("TEST_DIAG")[0],
            "recovery": {"counter": c, "session": s2, "txid": 2, "run": rrun, "announce": r.replies("INCREMENT", 2)[0], "diag": r.replies("TEST_DIAG", 1)[0]},
            "verdict": "COUNTED_PASS", "why": "", "events": r.events}


def corrupt(b, layout=0):
    """The corrupted-slot image: forge mode 1 changes bit 0 of the counter word of the newest slot and resets warm, and that boot starts a new era."""
    r = Runner(b)
    boot, s = r.bind()
    txids = [1, 2] if newest(b.slots, b.era) == layout else [1, 2, 3]
    counters = [r.increment(s, t) for t in txids]
    run = r.arm(13, 1)
    b.slots[8 * newest(b.slots, b.era) + 5] ^= 1
    b.marker = (run, 13, 1)
    b.boot(cold=False)
    r.rx(**b.announce())
    _, s2 = r.bind()
    r.diag(run)
    c = r.increment(s2, 1)
    rrun = r.f3(s2, 2)
    return {"kind": "corrupt", "run": run, "code": 13, "mode": 1, "layout": layout, "session": s, "txids": txids, "counters": counters, "boot_before": boot, "classes": ["UNKNOWN"] * len(txids),
            "after": r.replies("TEST_ARM"), "diag": r.replies("TEST_DIAG")[0],
            "recovery": {"counter": c, "session": s2, "txid": 2, "run": rrun, "announce": r.replies("INCREMENT", len(txids) + 1)[0], "diag": r.replies("TEST_DIAG", 1)[0]},
            "verdict": "COUNTED_PASS", "why": "", "events": r.events}


def campaign(trials=None, layout=0, corrupted=False, b=None):
    b = b or Board()
    recs = [sync(b)]
    for kind, code, mode in v.plan(trials is None, trials, layout, corrupted):
        recs.append(cold(b, code, mode, layout) if kind == "cold" else forge(b, mode) if kind == "forge" else corrupt(b, layout))
    return json.loads(json.dumps(recs))


def as_format(recs, fmt):
    """The same evidence in the shape an older runner wrote: v2 without the layout field, v1 also without host classification and raw bytes."""
    for t in recs:
        t.pop("layout", None)
        if fmt == "v1":
            t.pop("classes", None)
            t["events"] = [e for e in t["events"] if e["dir"] != "rxraw"]
    return recs


def reraw(recs):
    """Re-encodes the raw bytes and rebuilds the record copies from the recorded messages, so a changed message stays a well-formed, consistent frame."""
    for t in recs:
        ev = t["events"]
        for i, e in enumerate(ev):
            if e["dir"] == "rx" and e["msg"] and ev[i - 1]["dir"] == "rxraw":
                ev[i - 1]["hex"] = w.encode(e["msg"]).hex()
        if t["kind"] != "sync":
            t["after"], t["diag"] = replies(ev, "TEST_ARM"), (replies(ev, "TEST_DIAG") or [None])[0]
        if t["kind"] in ("forge", "corrupt"):
            t["recovery"]["announce"], t["recovery"]["diag"] = (replies(ev, "INCREMENT", 2) or [None])[0], (replies(ev, "TEST_DIAG", 1) or [None])[0]
    return recs


def rx(t, kind, nth=0):
    return [e for e in t["events"] if e["dir"] == "rx" and e["msg"]["type"] == kind][nth]["msg"]


def boot_msgs(recs, boot_id):
    return [e["msg"] for t in recs for e in t["events"] if e["dir"] == "rx" and e["msg"]["type"] == "ANNOUNCE" and e["msg"]["boot_id"] == boot_id]


def reseal(m, i):
    m[f"slot{8 * i + 7}"] = crc([m[f"slot{8 * i + k}"] for k in range(7)])


def verify(recs, *extra, trials=None, layout=0, fmt="v3"):
    with tempfile.TemporaryDirectory() as d:
        p = os.path.join(d, "e.jsonl")
        with open(p, "w") as f:
            f.writelines(json.dumps(t) + "\n" for t in recs)
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            rc = v.main([p, "--run", "0", *(["--pilot"] if trials is None else ["--trials", str(trials)]), "--layout", str(layout), "--format", fmt, *extra])
    return rc, out.getvalue()


class Verifier(unittest.TestCase):
    def fails(self, recs, why, *extra, trials=None, layout=0, fmt="v3"):
        rc, out = verify(recs, *extra, trials=trials, layout=layout, fmt=fmt)
        self.assertEqual(rc, 1, out)
        self.assertIn(why, out)

    def test_model_campaigns_pass(self):
        for trials in (None, 2):
            for layout in (0, 1):
                rc, out = verify(campaign(trials, layout), trials=trials, layout=layout)
                self.assertEqual(rc, 0, out)
        self.assertIn("records 17 of 17 planned, 0 failing", out)  # layout 1: sync and the 8 cold cases twice
        rc, out = verify(campaign(2), trials=2)
        self.assertIn("records 21 of 21 planned, 0 failing", out)

    def test_sync_after_a_commit_in_the_same_boot(self):
        # A commit made after the last boot, such as a journal trial's recovery commit, leaves the sync's bind ANNOUNCE (the boot-time snapshot) one counter behind the live journal
        b = Board()
        r = Runner(b)
        r.increment(r.bind()[1], 1)
        rc, out = verify(campaign(b=b))
        self.assertEqual(rc, 0, out)
        b = Board()
        r = Runner(b)
        s = r.bind()[1]
        for txid in (1, 2, 3):
            r.increment(s, txid)
        b.ann_slots, b.counter = list(b.slots), b.counter - 2  # the snapshot holds the commits, and the live counter runs below them
        self.fails(campaign(b=b), "slots do not hold the commit and its predecessor")

    def test_layout_1_rechecks(self):
        """The checks required before the slot 1 pilot, on v3 evidence with the newest commit in slot 1."""
        self.assertEqual(verify(campaign(layout=1), layout=1)[0], 0)
        recs = campaign(layout=1)
        del recs[2]["classes"]
        self.fails(recs, "fields missing ['classes']", layout=1)
        recs = campaign(layout=1)
        recs[2]["events"].insert(3, {"t": 0.0, "dir": "note", "hex": ""})
        self.fails(recs, "event not in the schema", layout=1)
        recs = campaign(layout=1)
        recs[2]["events"] = [e for e in recs[2]["events"] if e["dir"] != "rxraw"]
        self.fails(recs, "raw received bytes not recorded", layout=1)
        recs = campaign(layout=1)
        ev = recs[2]["events"]
        del ev[max(i for i, e in enumerate(ev) if e["dir"] == "rxraw")]  # the bytes of the last received frame missing
        self.fails(recs, "raw", layout=1)
        recs = campaign(layout=1)
        ev = recs[3]["events"]
        i = next(i for i, e in enumerate(ev) if e["dir"] == "rx" and e["msg"]["type"] == "EP1_REPLY")
        ev[i + 1:i + 1] = [{"t": 0.0, "dir": "rxraw", "hex": ""}, {"t": 0.0, "dir": "rx", "status": "OK", "msg": dict(rx(recs[3], "ANNOUNCE"), boot_id=999, nonce_echo=False, nonce=0)}]
        self.fails(reraw(recs), "received ['EP1_REPLY', 'ANNOUNCE']", layout=1)
        recs = campaign(layout=1)
        for m in boot_msgs(recs, rx(recs[1], "ANNOUNCE", 1)["boot_id"]):  # slot 0 one step above slot 1, both records valid
            m["slot6"] = m["slot14"] + 1
            reseal(m, 0)
        self.fails(reraw(recs), "slot 1 is not one seq step above slot 0", layout=1)
        recs = campaign(layout=1)
        self.fails(recs[:5], "records 5 of 9 planned", layout=1)
        self.assertEqual(verify(recs[:5], "--partial", layout=1)[0], 0)

    def test_corrupt_campaigns(self):
        """The corrupted-slot image: each layout passes, and each way the board could fail the rule, or the wrong image could answer, fails."""
        for trials in (None, 3):
            for layout in (0, 1):
                rc, out = verify(campaign(trials, layout, True), "--corrupt", trials=trials, layout=layout)
                self.assertEqual(rc, 0, out)
        self.fails(campaign(corrupted=True), "plan expects ('cold'")  # without --corrupt
        self.fails(campaign(), "plan expects ('corrupt'", "--corrupt")
        self.fails(campaign(corrupted=True), "record boot, session or layout differ", "--corrupt", layout=1)

        def boot_after(recs, change):
            for m in boot_msgs(recs, rx(recs[1], "ANNOUNCE", 1)["boot_id"]):
                change(m)
            return reraw(recs)
        self.fails(boot_after(campaign(corrupted=True), lambda m: m.update(slot5=m["slot5"] ^ 1)), "slot 0 is not the newest commit with only bit 0", "--corrupt")  # an intact slot, as the standard image leaves it
        self.fails(boot_after(campaign(corrupted=True), lambda m: m.update(slot5=m["slot5"] ^ 2)), "slot 0 is not the newest commit with only bit 0", "--corrupt")
        self.fails(boot_after(campaign(corrupted=True), lambda m: m.update(slot0=0)), "slot 0 is not the newest commit", "--corrupt")  # negative control: w0 at exactly 0 reads as an empty slot, not as corruption
        self.fails(boot_after(campaign(corrupted=True), lambda m: m.update(slot14=m["slot14"] + 1) or reseal(m, 1)), "slot 1 is not the intact predecessor", "--corrupt")
        self.fails(boot_after(campaign(corrupted=True), lambda m: m.update(retention_valid=True)), "corrupted slot accepted as valid retention", "--corrupt")
        recs = campaign(corrupted=True)
        recs[1]["classes"][-1] = "COMPLETED"
        self.fails(recs, "host classification", "--corrupt")
        recs = campaign(corrupted=True)
        del recs[1]["recovery"]
        self.fails(recs, "fields missing ['recovery']", "--corrupt")
        with self.assertRaises(SystemExit), contextlib.redirect_stderr(io.StringIO()):
            verify(campaign(corrupted=True), "--corrupt", fmt="v2")

    def test_plan_matches_the_runner(self):
        import cold_init_trials
        for args in ((True, None, 0, True), (True, None, 1, True), (False, 4, 1, True)):
            self.assertEqual(v.plan(*args), cold_init_trials.plan(*args), args)
        for args in ((True, None, 0), (True, None, 1), (False, 5, 0), (False, 3, 1)):
            self.assertEqual(v.plan(*args), cold_init_trials.plan(*args), args)

    def test_imports_nothing_from_the_host_tools(self):
        with open(v.__file__) as f:
            tree = ast.parse(f.read())
        names = {a.name for n in ast.walk(tree) if isinstance(n, ast.Import) for a in n.names} | {n.module for n in ast.walk(tree) if isinstance(n, ast.ImportFrom)}
        self.assertLessEqual(names, {"argparse", "json", "struct", "sys", "zlib"})

    def test_pre_trial_era(self):
        recs = campaign()
        self.assertEqual(rx(recs[2], "ANNOUNCE")["era"], 0)  # bound on the boot after a cold trial, as in the original verifier bug: must still pass
        old = rx(recs[1], "ANNOUNCE")["slot1"]
        b = rx(recs[2], "ANNOUNCE", 1)
        for m in boot_msgs(recs, b["boot_id"]):  # cold initialization left the old era in the commits
            m["slot1"] = m["slot9"] = old
            reseal(m, 0), reseal(m, 1)
        self.fails(reraw(recs), "is not a new era after cold initialization")
        recs = campaign()
        b = rx(recs[1], "ANNOUNCE", 1)
        for m in boot_msgs(recs, b["boot_id"]):  # bound on a valid journal, committed under another era
            m["slot1"] = m["slot9"] = 0x77
            reseal(m, 0), reseal(m, 1)
        self.fails(reraw(recs), "is not the era")

    def test_corrupted_slot_crc(self):
        recs = campaign()
        for m in boot_msgs(recs, rx(recs[4], "ANNOUNCE", 1)["boot_id"]):
            m["slot15"] ^= 1
        self.fails(reraw(recs), "slots do not hold the last two commits intact")

    def test_each_frame_check_rejects_its_mutation(self):
        """One mutation per frame-level check that no other test reached: each changed frame stays well formed, so only that check can reject it."""
        def boot_of(t, nth):
            return boot_msgs([t], rx(t, "ANNOUNCE", nth)["boot_id"])

        def drop_last_diag(recs):
            ev = recs[1]["events"]
            k = max(i for i, e in enumerate(ev) if e["dir"] == "tx" and e["note"] == "TEST_DIAG")
            del ev[k:]

        def retx(t, note, nth, **fields):
            e = [e for e in t["events"] if e["dir"] == "tx" and e["note"] == note][nth]
            m = dict(next(m for _, m in w.Parser().feed(bytes.fromhex(e["hex"]))), **fields)
            e["note"], e["hex"] = m["type"], w.encode(m).hex()

        def early_reply(recs):
            ev = recs[1]["events"]
            ev[0:0] = [dict(ev[1]), dict(ev[2])]

        def copy_pair(recs):
            for m in boot_of(recs[9], 1):
                m["slot4"] = m["slot12"] = 2
                reseal(m, 0)
                reseal(m, 1)

        def extra_request(recs):
            frame = w.encode({"type": "PROBE", "nonce": 9})
            recs[1]["events"].append({"t": 99.0, "dir": "tx", "note": "PROBE", "hex": frame.hex()})

        cases = [
            (lambda r: [m.update(retention_valid=True) for m in boot_of(r[9], 1)], "inconsistent pair accepted as valid retention"),
            (lambda r: rx(r[1], "TEST_ARM_ACK").update(run=rx(r[1], "TEST_ARM_ACK")["run"] + 1), "TEST_ARM_ACK does not echo the request"),
            (lambda r: rx(r[1], "HELLO_ACK").update(session=1), "START session does not match HELLO_ACK"),
            (lambda r: rx(r[1], "HELLO_ACK").update(challenge=1), "handshake values do not match"),
            (lambda r: rx(r[1], "ANNOUNCE").update(nonce=1), "ANNOUNCE nonce does not match the request"),
            (lambda r: rx(r[1], "EP1_REPLY").update(ep1_status=1), "not committed for the session"),
            (lambda r: rx(r[1], "TEST_DIAG_REPLY", 1).update(reset_cause=CAUSE | 1), "marker reset cause differs from the boot ANNOUNCE"),
            (lambda r: rx(r[1], "TEST_DIAG_REPLY", 0).update(marker_valid=1), "preparatory report does not carry the arm"),
            (lambda r: rx(r[0], "ANNOUNCE", 2).update(slot6=rx(r[0], "ANNOUNCE", 2)["slot6"] ^ 1), "two ANNOUNCEs of one boot carry different snapshots"),
            (lambda r: r[9].update(classes=["COMPLETED"]), "host classification ['COMPLETED'] differs from ['UNKNOWN']"),
            (lambda r: r[1].update(session=r[1]["session"] + 1), "record boot or session differs from the frames"),
            (lambda r: r[9].update(session=r[9]["session"] + 1), "record boot, session or txids differ from the frames"),
            (lambda r: r[1].update(txids=[1]), "txids [1]"),
            (lambda r: r[9]["counters"].__setitem__(0, r[9]["counters"][0] + 1), "recorded counters differ from the replies"),
            (lambda r: [m.update(retention_valid=False) for m in boot_of(r[0], 1)], "retention invalid after the F3 reset"),
            (lambda r: [m.update(slot13=m["slot13"] + 1) or reseal(m, 1) for m in boot_of(r[0], 1)], "slots do not hold"),
            (drop_last_diag, "TEST_DIAG never sent"),
            (lambda r: retx(r[0], "TEST_DIAG", 0, type="TEST_ARM", checkpoint=0, txid=0), "expected TEST_DIAG sent, found TEST_ARM"),
            (early_reply, "frames received before the first request"),
            (lambda r: [m.update(slot8=MAGIC) for m in boot_of(r[0], 0)], "retention reported valid over an inconsistent pair"),
            (lambda r: retx(r[0], "INCREMENT", 0, txid=7), "INCREMENT after the F3 arm differs"),
            (lambda r: [m.update(slot15=m["slot15"] ^ 1) for m in boot_of(r[9], 1)], "a forged slot is not valid on its own"),
            (copy_pair, "the pair is not a copy of the commit"),
            (lambda r: r[9]["recovery"].update(counter=2), "recovery session did not commit from counter 1"),
            (lambda r: r[9]["recovery"].update(run=r[9]["recovery"]["run"] + 1), "recovery F3 reset not under a new era"),
            (lambda r: rx(r[9], "EP1_REPLY", 1).update(counter=2), "txid 1 committed counter 2, expected 1"),  # the per-request counter check fires before the recovery check
            (extra_request, "unexpected request(s) after the trial"),
        ]
        for mutate, why in cases:
            with self.subTest(why=why):
                recs = campaign()
                mutate(recs)
                self.fails(reraw(recs), why)

    def test_classify_needs_the_session(self):
        r = [MAGIC, 0x200, 7, 0, 2, 2, 5]
        a = dict({f"slot{i}": x for i, x in enumerate(r + [crc(r)] + [0] * 8)}, era=0x200, retention_valid=True)
        self.assertEqual(v.classify(a, 7, 2), "COMPLETED")
        self.assertEqual(v.classify(a, 7, 3), "NOT_EXECUTED")
        self.assertEqual(v.classify(a, 8, 2), "UNKNOWN")  # the newest record belongs to another session
        self.assertEqual(v.classify(dict(a, retention_valid=False), 7, 2), "UNKNOWN")

    def test_corrupted_slot_is_corrupted_retention(self):
        words = []
        for txid, seq in ((2, 5), (1, 4)):
            r = [MAGIC, 0x200, 7, 0, txid, txid, seq]
            words += r + [crc(r)]
        a = dict({f"slot{i}": x for i, x in enumerate(words)}, era=0x200)
        self.assertEqual(v.newest(a), 0)
        for word in range(16):
            b = dict(a)
            b[f"slot{word}"] ^= 0x100 if word % 8 == 0 else 1
            self.assertEqual(v.newest(b), "inconsistent", word)
        self.assertEqual(v.newest(dict(a, slot0=0)), 1)  # w0 at 0 is an empty slot

    def test_missing_reset_evidence(self):
        recs = campaign()
        ev = recs[3]["events"]
        i = next(i for i, e in enumerate(ev) if e["dir"] == "rx" and e["msg"]["type"] == "TEST_DIAG_REPLY")
        del ev[i - 1:i + 1]
        self.fails(recs, "after TEST_ARM expected ['TEST_ARM_ACK', 'TEST_DIAG_REPLY', 'ANNOUNCE']")
        recs = campaign()
        for m in boot_msgs(recs, rx(recs[3], "ANNOUNCE", 1)["boot_id"]):
            m["reset_cause"] |= BOR
        self.fails(reraw(recs), "is not a software reset without brownout")
        recs = campaign()
        rx(recs[3], "TEST_DIAG_REPLY")["reset_cause"] = 0x04000000  # preparatory report: pin reset only
        self.fails(reraw(recs), "preparatory reset cause")
        recs = campaign()
        new, old = rx(recs[3], "ANNOUNCE", 1)["boot_id"], rx(recs[3], "ANNOUNCE")["boot_id"]
        for t in recs[3:]:
            for e in t["events"]:
                if e["dir"] == "rx" and e["msg"]["type"] == "ANNOUNCE" and e["msg"]["boot_id"] == new:
                    e["msg"]["boot_id"] = old
        self.fails(reraw(recs), "no new boot after the commanded reset")

    def test_unexplained_reset(self):
        recs = campaign()
        ev = recs[5]["events"]
        i = next(i for i, e in enumerate(ev) if e["dir"] == "rx" and e["msg"]["type"] == "EP1_REPLY")
        a = dict(rx(recs[5], "ANNOUNCE"), boot_id=999, nonce_echo=False, nonce=0)
        ev[i + 1:i + 1] = [{"t": 0.0, "dir": "rxraw", "hex": ""}, {"t": 0.0, "dir": "rx", "status": "OK", "msg": a}]
        self.fails(reraw(recs), "after INCREMENT expected ['EP1_REPLY'], received ['EP1_REPLY', 'ANNOUNCE']")
        recs = campaign()
        old = rx(recs[6], "ANNOUNCE")["boot_id"]
        for e in recs[6]["events"]:  # a reset between trials 5 and 6 that nobody commanded
            if e["dir"] == "rx" and e["msg"]["type"] == "ANNOUNCE" and e["msg"]["boot_id"] == old:
                e["msg"]["boot_id"] = 4242
        recs[6]["boot_before"] = 4242
        self.fails(reraw(recs), "boot changed without a commanded reset")

