    def test_retention_and_era_after_store(self):
        recs = campaign()
        for m in boot_msgs(recs, rx(recs[4], "ANNOUNCE", 1)["boot_id"]):  # store 10 judged warm, old store order: era kept
            m["era"], m["retention_valid"] = m["slot1"], True
        self.fails(reraw(recs), "does not match the interrupted store")
        recs = campaign()
        for m in boot_msgs(recs, rx(recs[8], "ANNOUNCE", 1)["boot_id"]):
            m["retention_valid"] = False
        self.fails(reraw(recs), "retention flag does not match the store and mode")

    def test_damaged_frames(self):
        recs = campaign()
        e = next(e for e in recs[3]["events"] if e["dir"] == "rxraw" and len(e["hex"]) > 40)
        e["hex"] = e["hex"][:20] + ("00" if e["hex"][20:22] != "00" else "11") + e["hex"][22:]
        self.fails(recs, "damaged frame(s) in the raw bytes")
        recs = campaign()
        last = [e for e in recs[3]["events"] if e["dir"] == "rxraw"][-1]
        last["hex"] = last["hex"][:-4]  # the last CRC byte and the delimiter lost to a reset
        self.fails(recs, "incomplete frame after the last delimiter")
        recs = campaign()
        ev = recs[3]["events"]
        i = next(i for i, e in enumerate(ev) if e["dir"] == "rx" and e["msg"]["type"] == "TEST_DIAG_REPLY")
        ev[i] = {"t": ev[i]["t"], "dir": "rx", "status": "ERR_CRC", "msg": None}
        self.fails(recs, "rejected by the host parser")
        recs = campaign()
        raws = [e for e in recs[3]["events"] if e["dir"] == "rxraw"]  # recorded messages kept, raw bytes of two frames swapped
        raws[0]["hex"], raws[1]["hex"] = raws[1]["hex"], raws[0]["hex"]
        self.fails(recs, "differ from the frames in the raw bytes")

    def test_formats(self):
        self.assertEqual(verify(as_format(campaign(), "v1"), fmt="v1")[0], 0)
        self.assertEqual(verify(as_format(campaign(), "v2"), fmt="v2")[0], 0)
        self.assertIn("NO raw received bytes", verify(as_format(campaign(), "v1"), fmt="v1")[1])
