    def test_layouts(self):
        recs = campaign(layout=1)
        self.assertEqual(rx(recs[1], "ANNOUNCE", 1)["slot14"] - rx(recs[1], "ANNOUNCE", 1)["slot6"], 1)  # slot 1 one seq step above slot 0
        self.fails(recs, "record layout 1 differs from --layout 0")
        for t in recs[1:]:
            t["layout"] = 0  # a record that claims the board trial layout over slots holding the other one
        self.fails(recs, "slots do not hold the last two commits intact with the newest in slot 0")
        recs = campaign(layout=1)
        recs[2]["layout"] = 0
        self.fails(recs, "record layout 0 differs from --layout 1", layout=1)
        recs = campaign()
        self.fails(recs, "record layout 0 differs from --layout 1", layout=1)
        recs = campaign(layout=1)
        for m in boot_msgs(recs, rx(recs[3], "ANNOUNCE", 1)["boot_id"]):  # slot 1 newest at store 10: slot 0, the predecessor, must lose only w0
            m["slot8"] = 0
        self.fails(reraw(recs), "slot w0 words do not match the interrupted store", layout=1)


